package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

var (
	uploadDir  = "/var/lib/artifacts/uploads"
	processDir = "/var/lib/artifacts/processing"
	mu         sync.Mutex
)

func hashFile(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	io.Copy(h, f)
	return hex.EncodeToString(h.Sum(nil)), nil
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "method not allowed", 405)
		return
	}
	file, header, err := r.FormFile("artifact")
	if err != nil {
		http.Error(w, "bad request", 400)
		return
	}
	defer file.Close()

	// Sanitize filename - remove directory components
	baseName := filepath.Base(header.Filename)
	if baseName == "." || baseName == "/" {
		http.Error(w, "invalid filename", 400)
		return
	}

	dstPath := filepath.Join(uploadDir, baseName)
	dst, err := os.Create(dstPath)
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}
	defer dst.Close()
	io.Copy(dst, file)

	w.WriteHeader(200)
	fmt.Fprintf(w, "uploaded: %s\n", baseName)
}

func handleProcess(w http.ResponseWriter, r *http.Request) {
	filename := r.URL.Query().Get("file")
	if filename == "" {
		http.Error(w, "missing file param", 400)
		return
	}

	// Only allow processing files that exist in upload dir
	srcPath := filepath.Join(uploadDir, filename)
	if _, err := os.Stat(srcPath); os.IsNotExist(err) {
		http.Error(w, "file not found", 404)
		return
	}

	mu.Lock()
	defer mu.Unlock()

	// Move to processing directory
	dstPath := filepath.Join(processDir, filename)
	os.Rename(srcPath, dstPath)

	// Run post-processing hook - uses filename for logging context
	// The hook script validates artifact integrity
	hookCmd := fmt.Sprintf("/usr/local/bin/process-artifact.sh '%s' '%s'", dstPath, time.Now().Format(time.RFC3339))
	cmd := exec.Command("/bin/sh", "-c", hookCmd)
	cmd.Dir = processDir
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("processing failed: %s", string(output)), 500)
		return
	}

	hash, _ := hashFile(dstPath)
	w.WriteHeader(200)
	fmt.Fprintf(w, "processed: %s sha256:%s\n", filename, hash)
}

func handleList(w http.ResponseWriter, r *http.Request) {
	entries, err := os.ReadDir(uploadDir)
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}
	var names []string
	for _, e := range entries {
		names = append(names, e.Name())
	}
	w.WriteHeader(200)
	fmt.Fprintf(w, "files: %s\n", strings.Join(names, ", "))
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	os.MkdirAll(uploadDir, 0755)
	os.MkdirAll(processDir, 0755)

	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/process", handleProcess)
	http.HandleFunc("/list", handleList)
	http.HandleFunc("/health", handleHealth)

	fmt.Println("artifact-processor listening on :8080")
	http.ListenAndServe(":8080", nil)
}
